"""Initial syllabus catalogue based on the supplied JNTUK R23 LDICA syllabus.
Detailed lesson expansions should be checked against the corresponding uploaded unit notes."""
def t(slug, title, summary, explanation, formula="", diagram_type="concept", applications=None):
    return {
        "slug": slug, "title": title, "summary": summary, "explanation": explanation,
        "formula": formula, "diagram_type": diagram_type,
        "applications": applications or [],
        "source_note": "Mapped to the supplied LDICA syllabus. Consult the matching unit PDF for complete derivations, circuit values, and exam-specific wording."
    }

UNITS = [
{"number": 1, "title": "Operational Amplifiers", "short": "Op-amps", "description": "Understand op-amp models, amplifier configurations, signal-processing circuits, comparators, and voltage regulators.", "topics": [
t("ideal-practical-opamp","Ideal and Practical Op-Amp","Compare the ideal model with real operational amplifiers.","An operational amplifier is a high-gain differential amplifier. The ideal model assumes infinite open-loop gain and input resistance, zero output resistance, and unlimited bandwidth. Practical devices have finite gain, offset voltage, bias currents, bandwidth, slew rate, and output limits.","Vout = Aol(V+ − V−)","opamp",["Signal conditioning","Analog computation"]),
t("opamp-characteristics","Op-Amp Characteristics","Learn the parameters used to describe op-amp performance.","Important characteristics include input offset voltage, input bias current, input resistance, output resistance, common-mode rejection ratio (CMRR), power-supply rejection ratio (PSRR), slew rate, gain-bandwidth product, and input/output range.","CMRR(dB) = 20 log10(Ad/Ac)","opamp"),
t("opamp-dc-ac","DC and AC Characteristics","Distinguish static errors from frequency-dependent behaviour.","DC characteristics describe offset and bias-related behaviour. AC characteristics describe how gain and phase vary with frequency, including bandwidth, slew-rate limits, and stability.","Gain-bandwidth product ≈ closed-loop gain × bandwidth (within the device's valid range)","chart"),
t("ic741","Features of the 741 Op-Amp","Study the commonly taught general-purpose 741 operational amplifier.","The 741 is a classic general-purpose bipolar op-amp used for studying amplifier configurations. Its real limits—supply range, input common-mode range, output swing, slew rate, and compensation—must be considered in circuit design.","Use the 741 datasheet for exact electrical limits.","opamp"),
t("inverting-amplifier","Inverting Amplifier","Calculate gain and understand the 180-degree phase reversal.","With negative feedback and ideal-op-amp assumptions, the inverting input is a virtual ground when the non-inverting input is grounded. Input current flows through the input resistor and feedback resistor.","Av = −Rf/Rin","opamp",["Signal scaling","Summing circuits"]),
t("non-inverting-amplifier","Non-Inverting Amplifier","Calculate gain without reversing signal phase.","The input is applied to the non-inverting terminal. A feedback divider sets the closed-loop gain; the output is in phase with the input under normal linear operation.","Av = 1 + Rf/Rg","opamp"),
t("differential-amplifier","Differential Amplifier","Amplify the difference between two input voltages.","A differential amplifier rejects signals common to both inputs while amplifying their difference. Resistor matching strongly affects common-mode rejection.","For a matched resistor-ratio circuit: Vout = (R2/R1)(V2 − V1)","opamp"),
t("instrumentation-amplifier","Instrumentation Amplifier","Learn accurate differential measurement with high input impedance.","Instrumentation amplifiers are designed for small differential signals in the presence of common-mode voltage. Typical features include high input impedance and high CMRR.","Gain depends on the selected instrumentation-amplifier topology.","opamp",["Sensor interfaces","Bridge measurements"]),
t("ac-amplifier","AC Amplifier","Understand amplification of time-varying signals.","AC amplifiers use coupling and feedback networks to amplify alternating signals. Coupling capacitors and parasitic components influence the lower and upper cutoff frequencies.","Voltage gain = Vout/Vin","waveform"),
t("differentiator","Op-Amp Differentiator","Relate output voltage to the rate of change of input.","An ideal inverting differentiator uses a capacitor at the input and a resistor in feedback. Practical designs limit high-frequency gain to reduce noise sensitivity.","Vout = −Rf C (dVin/dt)","opamp",["Edge detection","Wave shaping"]),
t("integrator","Op-Amp Integrator","Relate output voltage to the accumulated input.","An ideal inverting integrator uses an input resistor and feedback capacitor. A practical integrator often adds a resistor across the capacitor to control DC drift.","Vout = −(1/RC) ∫ Vin dt","opamp",["Ramp generation","Analog computation"]),
t("comparators","Comparators","Determine output state from the relative sizes of two inputs.","A comparator switches its output according to which input voltage is higher. Unlike a linear amplifier, it is normally used in open-loop switching operation.","Output state depends on the sign of (V+ − V−).","opamp",["Threshold detection","Level sensing"]),
t("schmitt-trigger","Schmitt Trigger","Use hysteresis to improve switching with noisy inputs.","A Schmitt trigger uses positive feedback to create distinct upper and lower switching thresholds. Hysteresis reduces repeated switching near a single threshold.","Threshold equations depend on the circuit and reference levels.","waveform"),
t("voltage-regulators","Introduction to Voltage Regulators","Understand the purpose of regulated power supplies.","A voltage regulator maintains an output voltage despite changes in input voltage or load current, within its operating limits. Linear regulators dissipate excess power as heat.","Approximate linear-regulator dissipation: P ≈ (Vin − Vout) Iout","block"),
t("ic723","Features of the 723 Voltage Regulator","Study the functional blocks and uses of the 723 regulator IC.","The 723 is a regulator IC used with external components to configure regulated supplies. Design depends on its reference, error amplifier, pass element arrangement, current limiting, and device ratings.","Use the supplied notes and device datasheet for configuration-specific equations.","block"),
t("three-terminal-regulators","Three-Terminal Voltage Regulators","Learn fixed and adjustable three-terminal regulator families.","Three-terminal regulators typically provide input, ground/common, and output connections. Selection requires checking input/output voltage, dropout, current rating, thermal limits, and protection features.","Power dissipation ≈ (Vin − Vout) Iout","block")
]},
{"number": 2, "title": "Op-Amp, IC 555 and IC 565 Applications", "short": "Filters and timers", "description": "Explore active filters, waveform generators, timer circuits, and phase-locked loops.", "topics": [
t("active-filters","Introduction to Active Filters","Understand filters built from amplifiers and passive components.","An active filter uses active devices such as op-amps together with resistors and capacitors to shape frequency response. Filters are classified by the frequencies they pass or attenuate.","First-order RC cutoff: fc = 1/(2πRC)","filter"),
t("band-pass-filter","Band-Pass Filters","Pass a selected range of frequencies.","A band-pass filter attenuates frequencies below its lower cutoff and above its upper cutoff. Its bandwidth is the difference between upper and lower cutoff frequencies.","BW = fH − fL","filter"),
t("band-reject-filter","Band-Reject Filters","Attenuate a selected frequency band.","A band-reject or band-stop filter reduces a band of frequencies while allowing frequencies outside that band to pass. A narrow rejection band is often called a notch.","f0 = √(fL fH) for the geometric centre frequency","filter"),
t("all-pass-filter","All-Pass Filters","Understand circuits that change phase while preserving ideal magnitude.","An all-pass filter ideally maintains constant magnitude response while changing phase with frequency. Practical performance depends on the circuit and component tolerances.","Magnitude ideally constant over the designed range.","filter"),
t("first-order-lpf","First-Order Low-Pass Butterworth Filter","Analyse a first-order low-pass response.","A low-pass filter passes lower frequencies and attenuates higher frequencies. A first-order response rolls off at approximately 20 dB per decade beyond cutoff. In an active implementation, the op-amp may provide passband gain.","fc = 1/(2πRC) for a single-pole RC network","filter"),
t("first-order-hpf","First-Order High-Pass Butterworth Filter","Analyse a first-order high-pass response.","A high-pass filter attenuates low frequencies and passes frequencies above its cutoff. Its frequency-determining resistor and capacitor roles are complementary to the simple low-pass network.","fc = 1/(2πRC) for a single-pole RC network","filter"),
t("triangular-generator","Triangular Waveform Generator","Understand how ramp segments combine into a triangular wave.","A common op-amp implementation combines a Schmitt trigger with an integrator. The comparator switches the ramp slope, and the integrator generates rising and falling linear segments.","Slope depends on input level, R, and C.","waveform"),
t("sawtooth-generator","Sawtooth Waveform Generator","Study circuits that produce a rapid reset and a ramp.","A sawtooth generator creates a ramp followed by a comparatively rapid return to its starting level. The exact circuit determines linearity and reset behaviour.","Ramp slope depends on the charging current and capacitance.","waveform"),
t("square-wave-generator","Square-Wave Generator","Learn regenerative switching for periodic output.","An op-amp relaxation oscillator uses positive feedback and a timing network to repeatedly switch between output states. The resulting waveform is approximately rectangular.","Frequency depends on threshold ratio and RC timing network.","waveform"),
t("ic555-functional","IC 555 Timer Functional Diagram","Identify the internal functional blocks of a 555 timer.","The 555 timer uses a resistor divider, comparators, a latch, a discharge transistor, and an output stage. The classic internal divider establishes nominal trigger and threshold levels near one-third and two-thirds of the supply.","Nominal comparator levels: VCC/3 and 2VCC/3","block"),
t("ic555-monostable","IC 555 Monostable Operation","Understand one stable state and a triggered timing pulse.","In monostable operation, a trigger starts a temporary output pulse. The timing capacitor charges until the threshold comparator resets the latch.","Classic timing approximation: T ≈ 1.1RC","waveform"),
t("ic555-astable","IC 555 Astable Operation","Understand continuous oscillation with a 555 timer.","In astable operation, the capacitor repeatedly charges and discharges between internal threshold levels, producing a continuous output waveform. Timing depends on RA, RB, and C in the usual circuit.","Classic configuration: TH ≈ 0.693(RA+RB)C; TL ≈ 0.693RBC","waveform"),
t("ic555-applications","Applications of IC 555","Connect timer operating modes to practical tasks.","Applications include time delays, pulse generation, oscillators, missing-pulse detection, and other timing circuits. The exact application depends on the selected circuit and component values.","Calculate timing from the chosen topology.","block"),
t("ic565-pll","IC 565 PLL Block Diagram","Identify the main functional blocks in a phase-locked loop.","A PLL compares the phase of an input with a feedback signal, filters the phase-detector output, and controls a voltage-controlled oscillator. The IC 565 is a classic PLL device studied in analogue communication circuits.","Operating range and centre frequency depend on external components and device conditions.","block"),
t("pll-principle","Phase-Locked Loop Operating Principle","Explain acquisition, lock, and tracking.","A PLL adjusts oscillator frequency and phase until its feedback signal aligns with the reference input within the loop's lock range. Capture and lock ranges are distinct and depend on loop design.","Loop behaviour depends on detector, filter, and VCO characteristics.","block"),
t("ic565-applications","Applications of IC 565","Study classic PLL applications.","PLL applications include frequency tracking, demodulation, frequency synthesis-related circuits, and signal synchronization. Design must respect the device's operating range and external-component requirements.","Refer to the specific IC 565 circuit in the supplied notes.","block")
]},
{"number": 3, "title": "Data Converters", "short": "DAC and ADC", "description": "Learn digital-to-analogue and analogue-to-digital conversion, architectures, specifications, and calculations.", "topics": [
t("data-converter-intro","Introduction to Data Converters","Understand why analogue and digital representations are converted.","A DAC converts a digital code to an analogue quantity; an ADC converts an analogue input to a digital code. Converter choice depends on speed, resolution, accuracy, input range, and cost.","For N bits there are 2^N possible codes.","block"),
t("basic-dac","Basic DAC Techniques","Understand digital code weighting and analogue output.","DAC circuits combine reference levels according to a digital input code. Architectures trade component matching, speed, complexity, and output accuracy.","Ideal step size depends on reference range and number of bits.","block"),
t("weighted-resistor-dac","Weighted-Resistor DAC","Study a binary-weighted summing amplifier DAC.","A weighted-resistor DAC uses resistor values weighted by powers of two so each digital input contributes a different amount to the summing node. Accurate resistor ratios are important.","For an ideal inverting implementation, Vout = −Rf Σ(Vi/Ri).","circuit"),
t("r2r-ladder-dac","R-2R Ladder DAC","Learn a DAC architecture using two resistor values.","An R-2R ladder repeatedly divides current or voltage using only R and 2R branches. This makes resistor matching easier than a wide range of binary-weighted resistors.","Output depends on bit pattern, reference, topology, and output scaling.","circuit"),
t("inverted-r2r-dac","Inverted R-2R DAC","Study the inverted ladder arrangement from the course notes.","The inverted R-2R DAC is a ladder-based conversion arrangement. Analyse the resistor network and current paths using the exact circuit topology shown in the supplied unit notes; do not assume every inverted topology has identical output polarity.","Use the circuit-specific transfer equation from the lesson derivation.","circuit"),
t("parallel-comparator-adc","Parallel-Comparator (Flash) ADC","Understand high-speed conversion using parallel comparators.","A flash ADC compares the input against multiple reference thresholds in parallel and encodes the comparator pattern. An N-bit flash converter typically requires 2^N − 1 comparators.","Comparator count = 2^N − 1","block"),
t("counter-adc","Counter-Type ADC","Understand conversion by counting DAC steps.","A counter-type ADC increments a digital counter, converts the count through a DAC, and compares the DAC output with the input. It is simple but conversion time depends on the input level.","Worst-case count grows with 2^N.","block"),
t("sar-adc","Successive-Approximation ADC","Learn bit-by-bit binary search conversion.","A SAR ADC tests candidate bits from most significant to least significant using a DAC and comparator. This usually requires approximately one decision cycle per output bit after conversion starts.","Conversion decision count is approximately N for an N-bit SAR.","block"),
t("dual-slope-adc","Dual-Slope ADC","Understand integrate-and-deintegrate conversion.","A dual-slope ADC integrates the input for a fixed interval and then applies a reference of opposite polarity until the integrator returns to its baseline. The measured deintegration time represents the input magnitude.","Ideal ratio cancels many integrator component tolerances when timing conditions are controlled.","block"),
t("dac-specifications","DAC Specifications","Compare resolution, accuracy, linearity, and settling behaviour.","Important DAC specifications include resolution, offset error, gain error, integral and differential nonlinearity, monotonicity, settling time, and output range.","Ideal LSB size depends on the stated full-scale convention and number of bits.","chart"),
t("adc-specifications","ADC Specifications","Understand the metrics used to compare ADCs.","Important ADC specifications include resolution, quantization error, offset and gain errors, INL, DNL, conversion time, sampling rate, input range, and signal-to-noise performance.","Ideal quantization step is approximately full-scale range / 2^N under the common step-size convention.","chart")
]},
{"number": 4, "title": "Combinational Logic ICs", "short": "Digital logic", "description": "Design combinational circuits using standard TTL and CMOS logic IC families.", "topics": [
t("ttl-74xx","TTL 74XX Series Specifications and Applications","Understand logic-family parameters and standard TTL devices.","TTL 74XX devices implement common logic functions. Important parameters include supply conditions, logic-level limits, propagation delay, power consumption, fan-out, and output drive. Exact specifications vary by device and subfamily.","Always use the selected IC's datasheet for exact limits.","logic"),
t("cmos-40xx","CMOS 40XX Series Specifications and Applications","Understand CMOS logic behaviour and common device families.","CMOS 40XX devices cover logic gates and other functions. Input impedance, supply range, speed, output drive, and unused-input handling depend on the specific device and family.","Check the particular IC datasheet before selecting electrical limits.","logic"),
t("code-converters","Code Converters","Convert information between binary coding systems.","A code converter maps input code words to corresponding output code words. Design usually begins with a mapping table, followed by Boolean simplification and logic implementation.","Derive Boolean functions from the complete truth table.","logic"),
t("decoders","Decoders","Activate an output based on an input code.","A decoder maps an n-bit input code to one of up to 2^n output lines, often with enable inputs and active-low or active-high outputs.","Maximum output lines for n inputs = 2^n","logic"),
t("led-lcd-decoders","LED and LCD Decoders with Drivers","Connect coded inputs to display elements.","Display decoders translate binary-coded input into segment-control signals. LED and LCD displays have different drive requirements; polarity and current handling depend on display type and IC.","Use the exact display type and decoder truth table.","logic"),
t("encoders","Encoders","Convert an active input line into a coded output.","An encoder produces a binary code corresponding to an asserted input. Basic encoders require a defined input condition; simultaneous active inputs need priority handling or another defined scheme.","For 2^n distinct input lines, n output bits can encode their index.","logic"),
t("priority-encoders","Priority Encoders","Resolve multiple active inputs according to priority.","A priority encoder outputs the code of the highest-priority asserted input and may provide a valid-output indicator.","Priority order and active-level conventions are device-specific.","logic"),
t("multiplexers","Multiplexers","Select one of several inputs for a shared output.","A multiplexer uses select lines to route one of its data inputs to an output. It can also implement Boolean functions by assigning truth-table values to data inputs.","Select lines for 2^n inputs = n","logic"),
t("demultiplexers","Demultiplexers","Route one input to a selected output.","A demultiplexer uses select lines to route a data input to one of multiple outputs. Enable and output polarity vary by IC.","Select lines for 2^n outputs = n","logic"),
t("priority-generators-checkers","Priority Generators and Checkers","Study priority-related logic and code checking functions.","Priority-related circuits generate or validate structured code conditions. The precise functions and terminology should follow the specific circuit covered in the supplied course notes.","Derive each output from the stated truth table.","logic"),
t("parallel-binary-adder","Parallel Binary Adders","Add multi-bit binary numbers using connected stages.","A parallel adder combines bitwise sum and carry logic across multiple positions. Ripple-carry designs are straightforward, but carry propagation affects delay.","Full adder: S = A ⊕ B ⊕ Cin; Cout = AB + ACin + BCin","logic"),
t("parallel-binary-subtractor","Parallel Binary Subtractors","Perform multi-bit binary subtraction.","A subtractor calculates a difference and borrow. Many adder-subtractor designs use two's-complement arithmetic and XOR-controlled input inversion.","A − B = A + (two's complement of B)","logic"),
t("magnitude-comparators","Magnitude Comparators","Determine whether one binary word is less than, equal to, or greater than another.","A magnitude comparator compares two binary words from the most significant bit downward and produces relational outputs.","Outputs typically represent A>B, A=B, and A<B.","logic")
]},
{"number": 5, "title": "Sequential Logic ICs and Memories", "short": "Sequential circuits", "description": "Study state storage, flip-flops, counters, shift registers, and semiconductor memories.", "topics": [
t("sequential-ics","Common 74XX and CMOS 40XX Sequential ICs","Recognize common sequential logic device families.","Sequential ICs implement storage and state-transition functions. Device selection requires checking clocking, reset/set behaviour, logic family, pinout, speed, and supply constraints.","Refer to the selected device datasheet.","logic"),
t("sr-flip-flop","SR Flip-Flop","Understand set, reset, hold, and invalid input conditions.","An SR flip-flop stores one bit. Its behaviour depends on the implementation, active input levels, and whether it is gated or clocked; the forbidden or indeterminate input combination must be identified for the chosen circuit.","Build the truth table for the exact NOR/NAND or clocked implementation.","logic"),
t("jk-flip-flop","JK Flip-Flop","Understand the JK storage element and toggle condition.","A JK flip-flop improves on the basic SR form by defining the J=K=1 condition as toggling for the active clock event, subject to the device's triggering behaviour.","Characteristic relation: Q(next) = J·not(Q) + not(K)·Q for a conventional edge-triggered JK model.","logic"),
t("d-flip-flop","D Flip-Flop","Understand storage of the sampled data input.","A D flip-flop transfers the D input to Q at the active clock edge and holds that value until the next active edge, subject to asynchronous control inputs.","Q(next) = D at the active clock edge","logic"),
t("t-flip-flop","T Flip-Flop","Understand conditional toggling of stored state.","A T flip-flop holds its state when T=0 and toggles when T=1 at the active clock event.","Q(next) = Q XOR T","logic"),
t("synchronous-counters","Synchronous Counters","Design counters whose flip-flops share a clock.","In a synchronous counter, the active clock reaches all flip-flops together and combinational logic determines each next state. This avoids ripple clocking between stages, though logic propagation delays remain.","An n-bit binary counter has up to 2^n states.","logic"),
t("decade-counters","Decade Counters","Build a ten-state counting sequence.","A decade counter cycles through ten states, commonly representing decimal digits 0 through 9. The design must define the transition out of the ninth state and the reset behaviour.","Required state count = 10; minimum binary state bits = 4","logic"),
t("shift-registers","Shift Registers","Understand serial and parallel data movement.","A shift register is a group of storage elements that moves data between stages under control of clock events. Common modes are SISO, SIPO, PISO, and PIPO.","An n-stage register stores n bits.","logic"),
t("rom-architecture","ROM Architecture","Understand address decoding and stored output words.","Read-only memory uses address inputs to select stored data. Capacity is described by the number of words and bits per word; ROM variants differ in how data is programmed or changed.","Capacity in bits = number of words × bits per word","block"),
t("rom-types-applications","Types and Applications of ROM","Compare common ROM technologies.","Common categories include mask ROM, PROM, EPROM, EEPROM, and flash memory. They differ in programming method, erasability, endurance, and retention.","Check the specific technology for programming and erase constraints.","block"),
t("ram-architecture","RAM Architecture","Understand address, data, and control organisation.","Random-access memory provides read and write access to addressed locations. Architecture includes storage cells, address decoding, data paths, and control signals.","Capacity = number of addressable words × bits per word","block"),
t("static-ram","Static RAM (SRAM)","Learn storage using bistable circuits.","SRAM stores bits in bistable cell circuits and normally does not require periodic refresh while powered. It is commonly used where speed is important, with area and cost trade-offs.","Capacity calculations depend on word count and word width.","block"),
t("dynamic-ram","Dynamic RAM (DRAM)","Learn storage using capacitive charge.","DRAM stores information as charge in memory cells and requires refresh because the stored charge leaks. It generally offers higher density than SRAM.","Capacity calculations depend on word count and word width.","block")
]}
]
